'use strict';
// User-supplied recordings; offline originals, indexed variants for correct answers.
const BundledCheers=(()=>{const files={"start":"","question":[""],"correct":["",""],"shoot":"","goal":"","retry":[""],"clear":""},cache=new Map();function count(event){return Array.isArray(files[event])?files[event].length:files[event]?1:0;}function blob(event,index=0){if(!count(event))return null;const key=event+':'+index;if(!cache.has(key)){const file=Array.isArray(files[event])?files[event][index]:files[event];if(!file)return null;const raw=atob(file),bytes=Uint8Array.from(raw,c=>c.charCodeAt(0));cache.set(key,new Blob([bytes],{type:'audio/mpeg'}));}return cache.get(key);}return{blob,count};})();
